const SHADOW_THEMES=[
 {id:'patterns',icon:'🔍',title:'Understand a Pattern',summary:'Notice what keeps coming up, without judging yourself.',prompts:['What situation or reaction have I noticed more than once?','What feeling or need might be underneath it?','What small response could I try next time?']},
 {id:'kindness',icon:'💗',title:'Practice Self-Compassion',summary:'Make room for your imperfect, human side.',prompts:['What part of myself have I been judging lately?','If a friend felt this way, what would I say to them?','What is one kind thing I can offer myself today?']},
 {id:'boundaries',icon:'🗝️',title:'Find My Boundaries',summary:'Listen to discomfort and protect what matters.',prompts:['When did I feel uncomfortable or stretched too thin?','What need or value might that feeling be pointing to?','What respectful boundary could I communicate?']},
 {id:'release',icon:'🍂',title:'Release What I Can',summary:'Separate what you can influence from what you cannot.',prompts:['What feels heavy on my mind right now?','Which part of this situation is within my control?','What is one manageable next step or thing I can set down?']}
];
function shadowWork(){
 const theme=SHADOW_THEMES.find(t=>t.id===state.shadowTheme);
 const step=Math.max(0,Math.min(2,state.shadowStep||0));
 const answers=theme?(state.shadowAnswers[theme.id]||[]):[];
 const cards=SHADOW_THEMES.map(t=>'<button type="button" class="shadow-theme '+(t.id===state.shadowTheme?'is-active':'')+'" data-action="shadow-theme" data-theme="'+t.id+'" aria-pressed="'+(t.id===state.shadowTheme?'true':'false')+'"><span class="shadow-theme-icon" aria-hidden="true">'+t.icon+'</span><strong>'+e(t.title)+'</strong><small>'+e(t.summary)+'</small></button>').join('');
 return '<style>'+
 '.shadow-journey{border-radius:26px;padding:clamp(18px,3.5vw,36px);background:radial-gradient(ellipse at 85% 0%,#8d617a88 0%,transparent 47%),linear-gradient(145deg,#231c38,#42304e 63%,#493247);border:1px solid #d7ad9e;color:#fff8f3;box-shadow:0 18px 55px #1f112d5c;max-width:1060px;margin:15px auto 36px;position:relative;isolation:isolate}.shadow-journey *{box-sizing:border-box}.shadow-journey h2,.shadow-journey h3,.shadow-journey strong{color:#fff7ef}.shadow-heading{text-align:center;max-width:720px;margin:8px auto 26px}.shadow-heading .eyebrow{text-transform:uppercase;letter-spacing:.19em;font-size:.75rem;color:#eac5a9}.shadow-heading h2{font-family:Georgia,serif;font-size:clamp(2rem,4vw,3.25rem);margin:9px 0 13px}.shadow-heading p{line-height:1.65;color:#f4dfe8}.shadow-theme-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.shadow-theme{display:flex;flex-direction:column;align-items:flex-start;gap:9px;text-align:left;border:1px solid #d5adab;background:linear-gradient(145deg,#76546ba8,#3d3053de);border-radius:19px;padding:21px;cursor:pointer;min-width:0;min-height:150px;color:#fff}.shadow-theme-icon{font-size:2rem;line-height:1}.shadow-theme strong{font-size:1.1rem}.shadow-theme small{color:#f1dce6;font-size:.9rem;line-height:1.45}.shadow-theme.is-active{outline:2px solid #ffe2ad;background:linear-gradient(145deg,#8a6382,#553855)}.shadow-theme:focus-visible,.shadow-controls button:focus-visible,.shadow-ground-toggle:focus-visible{outline:3px solid #ffe7a0;outline-offset:3px}.shadow-guide{margin-top:24px;padding:clamp(17px,3vw,28px);border-radius:18px;border:1px solid #d4b19d;background:#fff4eb;color:#402d40}.shadow-guide h3{font-size:clamp(1.25rem,2.4vw,1.65rem);color:#482f49}.shadow-guide p{color:#58465a;line-height:1.6}.shadow-guide .shadow-step-label{font-size:.81rem;font-weight:800;color:#7d5071;letter-spacing:.06em}.shadow-progress{height:7px;background:#e8d3dc;border-radius:99px;overflow:hidden;margin:12px 0 19px}.shadow-progress span{display:block;height:100%;background:linear-gradient(90deg,#a95d94,#dbac82);border-radius:inherit}.shadow-guide label{display:block;font-weight:750;color:#482f49;margin:13px 0}.shadow-guide textarea{display:block;width:100%;min-height:150px;resize:vertical;padding:14px;border-radius:13px;border:1px solid #ae88ad;background:#fffdfb;color:#332337;font:inherit;line-height:1.6;box-shadow:none}.shadow-guide textarea:focus-visible{outline:3px solid #be83a9;outline-offset:2px}.shadow-controls{display:flex;flex-wrap:wrap;gap:10px;margin-top:15px;align-items:center}.shadow-controls button,.shadow-ground-toggle{padding:11px 17px;border-radius:22px;border:1px solid #6a4664;background:#573650;color:#fff;font:inherit;font-weight:700;cursor:pointer}.shadow-controls button.alt,.shadow-ground-toggle{background:#fff7ee;color:#49314b;border:1px solid #b997a7}.shadow-controls button:disabled{opacity:.45;cursor:default}.shadow-success{margin:14px 0 0;padding:12px;border-radius:12px;color:#315443;background:#ddf0e6;font-weight:700}.shadow-gentle{font-size:.9rem;color:#efdae3;line-height:1.55;margin:17px 0 2px}.shadow-ground{margin-top:14px;border:1px solid #e0bed1;border-radius:14px;padding:16px;background:#563b59;color:#fff5ed}.shadow-ground p{margin:7px 0;color:#f6e4ec;line-height:1.6}.shadow-mini-note{font-size:.86rem;color:#684e64!important}.shadow-guide .shadow-controls button{background:#573650;color:#fff}.shadow-guide .shadow-controls button.alt{background:#fff7ee;color:#49314b}.shadow-journey .shadow-ground-toggle{margin-top:12px}.shadow-journey .shadow-preview-note{font-size:.84rem;line-height:1.5;color:#eed9e4}.shadow-journey .shadow-theme:hover{filter:brightness(1.08)}'+
 '@media(max-width:590px){.shadow-theme-grid{grid-template-columns:1fr}.shadow-theme{min-height:100px;padding:17px}.shadow-journey{border-radius:16px;padding:16px}.shadow-guide{padding:16px}.shadow-guide textarea{min-height:120px}.shadow-controls button{flex:1}}'+
 '</style><section class="shadow-journey" aria-label="Shadow Work Journey"><header class="shadow-heading"><div class="eyebrow">🌗 A quiet moment for yourself</div><h2>Meet Yourself With Curiosity</h2><p>Shadow work means noticing feelings, habits and reactions we sometimes avoid. You do not need to relive painful experiences. Choose a theme, respond at your own pace, and skip anything that does not feel right.</p></header><section class="shadow-guide" aria-label="An example of shadow work" style="margin:0 0 22px"><h3>✦ How does shadow work help?</h3><p>Imagine wanting to try something new, but hearing a thought like “I am not good enough” and talking yourself out of it. You can gently explore that pattern without blaming yourself.</p><ol style="line-height:1.7;padding-left:24px"><li><strong style="color:#482f49">Notice:</strong> What do I keep doing that holds me back?</li><li><strong style="color:#482f49">Understand:</strong> What fear or belief might be behind it?</li><li><strong style="color:#482f49">Question:</strong> Is that belief actually true?</li><li><strong style="color:#482f49">Choose:</strong> What small, kinder response could I try?</li></ol><p>Some barriers are outside our control. Shadow work is about finding choices where we have them, not blaming ourselves for everything.</p></section><h3>Choose a path to explore</h3><div class="shadow-theme-grid">'+cards+'</div>'+
 (theme?'<section class="shadow-guide" id="shadow-guide"><div class="shadow-step-label">'+e(theme.title)+' · Question '+(step+1)+' of '+theme.prompts.length+'</div><div class="shadow-progress" role="progressbar" aria-label="Reflection progress" aria-valuenow="'+(step+1)+'" aria-valuemin="1" aria-valuemax="3"><span style="width:'+((step+1)/3*100)+'%"></span></div><h3>'+e(theme.prompts[step])+'</h3><label for="shadow-answer">Your private reflection (optional)</label><textarea id="shadow-answer" maxlength="4000" placeholder="Write what feels helpful, or leave this blank to skip.">'+e(answers[step]||'')+'</textarea><p class="shadow-mini-note">Your writing is not saved until you choose Save to Journal. You can change themes or stop at any time.</p><div class="shadow-controls"><button type="button" data-action="shadow-prev" class="alt" '+(step===0?'disabled':'')+'>← Previous</button><button type="button" data-action="shadow-next" '+(step===2?'disabled':'')+'>Next / Skip →</button><button type="button" data-action="shadow-save">💗 Save to Journal</button><button type="button" data-action="shadow-reset" class="alt">Clear my answers</button></div>'+(state.shadowMessage?'<p class="shadow-success" role="status">'+e(state.shadowMessage)+'</p>':'')+'</section>':'')+
 '<p class="shadow-gentle">✦ It is okay to pause. This is an optional journaling exercise, not therapy, diagnosis, or a test. If reflection feels overwhelming, stop and connect with someone you trust.</p><button type="button" class="shadow-ground-toggle" data-action="shadow-ground" aria-expanded="'+(state.shadowGround?'true':'false')+'">🌿 '+(state.shadowGround?'Hide grounding pause':'Take a grounding pause')+'</button>'+
 (state.shadowGround?'<div class="shadow-ground"><strong>Come back to the present</strong><p>Feel your feet on the ground. Look around and name three things you can see. Take a comfortable breath, and choose whether to continue or finish for today.</p></div>':'')+
 '<p class="shadow-preview-note">Reflections saved to your Journal remain in this browser; they do not automatically sync between devices. Nothing is posted publicly.</p></section>';
}
function shadowCaptureAnswer(){
 const t=SHADOW_THEMES.find(x=>x.id===state.shadowTheme),el=document.getElementById('shadow-answer');
 if(!t||!el)return;
 const arr=(state.shadowAnswers[t.id]||[]).slice();arr[state.shadowStep||0]=el.value;
 state.shadowAnswers[t.id]=arr;
}
function shadowSaveToJournal(){
 shadowCaptureAnswer();
 const t=SHADOW_THEMES.find(x=>x.id===state.shadowTheme);if(!t)return;
 const arr=state.shadowAnswers[t.id]||[];
 const meaningful=t.prompts.map((q,i)=>({q,a:(arr[i]||'').trim()})).filter(x=>x.a);
 if(!meaningful.length){state.shadowMessage='Write at least one reflection before saving. Skipping is always okay.';render();return;}
 const entry=meaningful.map(x=>x.q+'\n'+x.a).join('\n\n');
 try{save('Shadow Work · '+t.title,entry);state.shadowMessage='Saved privately to your Journal on this browser.';}
 catch{state.shadowMessage='Could not save here. Please check your browser storage settings.';}
 render();
}

const TOOL_EXPLAINERS={"natal":["What is a birth chart?","A birth chart is an astrology map of where the Sun, Moon and planets appeared at the moment you were born. People use it to reflect on personality, strengths and life themes.","Enter your birth date, time and place, then explore what each placement traditionally symbolizes.","Astrology is a symbolic tradition, not a scientific way to predict your future."],"moon":["What is a natal Moon phase?","The Moon changes appearance as it moves through its roughly monthly cycle. Your natal Moon phase is the phase that appeared when you were born.","Enter your birth details and learn about the Moon phase and its traditional symbolism.","You can enjoy the symbolism without treating it as a rule about who you are."],"bazi":["What are Chinese Zodiac and BaZi?","The Chinese zodiac uses a repeating twelve-animal cycle. BaZi, also called the Four Pillars of Destiny, is a traditional Chinese system based on birth year, month, day and hour.","Enter your birth details to explore the traditional animal and element themes.","These are traditions with their own history, not guarantees about personality or destiny."],"houses":["What are astrology houses?","Astrologers divide a birth chart into twelve houses, representing different life areas such as home, relationships, work and community.","Browse each house to see what part of life it traditionally describes.","The houses are an interpretive astrology framework, not a scientific assessment."],"asteroids":["What are asteroids in astrology?","Beyond the familiar planets, some astrologers also study asteroids such as Ceres, Juno and Vesta. Each is assigned symbolic themes.","Explore their placements and the stories attached to their names.","These interpretations are symbolic; they do not determine events or relationships."],"astro":["What is astrocartography?","Astrocartography is an astrology technique that draws your birth-chart planet lines across a world map. People use it to explore the symbolic meaning of places.","Enter your birth date, accurate birth time and birthplace, then explore the lines on the map.","These lines are not scientific evidence that a city will bring love, money or success."],"calendar":["What is a 13-month calendar?","This is an alternative way of organizing a year into thirteen periods. Our version uses an equinox-based structure for reflection and planning.","Open the calendar and compare its dates and themes with the familiar calendar.","It is an optional calendar system, not a replacement for legal or official dates."],"life":["What is a Life Path number?","In numerology, a Life Path number is calculated from your birth date and given a symbolic meaning.","Enter your birthday, see the calculation and read about the themes linked to the result.","Numerology is a reflective tradition, not a measurement of your abilities."],"numbers":["What is numerology?","Numerology explores the meanings people traditionally assign to numbers. You may see Life Path numbers, master numbers and Tarot number correspondences.","Start with your birthday or browse the meanings at your own pace.","Numbers do not control your worth or your future."],"love":["What is zodiac compatibility?","Zodiac compatibility compares the traditional qualities of two astrology Sun signs. It can offer fun conversation starters about connection and differences.","Choose both signs, then explore emotional, communication and trust themes together.","No sign combination can tell you whether a real relationship will succeed."],"sound":["What are sound frequencies?","A sound frequency measures how fast a tone vibrates, in hertz (Hz). Some spiritual communities give certain frequencies symbolic meanings.","Choose a gentle tone and listen at a comfortable volume if audio is available.","Specific frequencies have not been established as cures or guaranteed healing treatments."],"rituals":["What is a ritual?","A ritual is an intentional sequence of actions that carries meaning. Some rituals belong to living religions and cultures; others are modern personal reflections.","Open a collection or the little e-book to learn about the practice and its context.","We distinguish documented traditions from modern adaptations and respect community boundaries."],"cycle":["What is a cycle tracker?","A menstrual cycle tracker records dates to help you notice patterns over time. This page adds optional moon imagery for reflection.","Enter a recent period start date and average cycle length for a rough estimate.","Dates are estimates only. Do not rely on them for birth control or a medical diagnosis."],"shadow":["What is shadow work?","Shadow work means exploring the beliefs, fears and automatic habits that may hold you back. It can help you notice a pattern, understand its origins, question an old belief and choose a healthier response.","Start with a gentle theme, answer a question at a time, and skip anything that feels too personal.","It is not self-blame or therapy. Many obstacles are external, and you are free to stop."],"runes":["What is divination with runes?","Divination is using symbols, cards or other traditional tools to explore questions and possibilities. Runes are letters from historical Germanic alphabets that some modern practitioners use symbolically.","Draw runes and reflect on which themes connect with your question.","A rune draw is for reflection, not proof of what will happen."],"pendulum":["What is pendulum divination?","A pendulum is a small weight suspended from a cord or chain. In some spiritual practices, its movements are interpreted symbolically when asking questions.","Ask a question and use the response as a starting point for your own reflection.","Real pendulum motion can be influenced by small unconscious movements; do not use it for major safety or medical decisions."],"oracle":["What is an oracle?","An oracle is a message or symbol used for contemplation. Here, Mystic Companion offers reflective responses to the questions you ask.","Type a question about a feeling, decision or intention and consider the response thoughtfully.","It is not a supernatural certainty, professional advice or a substitute for your judgment."],"store":["What is the Creator Store?","The Creator Store is a place to explore SpiritualVibz and NeuroSpicy Mystic products and offerings.","Browse what interests you and check product details and prices before purchasing.","Payments should take place through a clearly identified, secure checkout."]};
