 if(a==='shadow-theme'){shadowCaptureAnswer();const t=SHADOW_THEMES.find(x=>x.id===b.dataset.theme);if(t){state.shadowTheme=t.id;state.shadowStep=0;state.shadowMessage='';render();document.querySelector('#shadow-guide')?.scrollIntoView({block:'nearest'});}return;}
 if(a==='shadow-prev'||a==='shadow-next'){shadowCaptureAnswer();state.shadowStep=Math.max(0,Math.min(2,(state.shadowStep||0)+(a==='shadow-next'?1:-1)));state.shadowMessage='';render();document.querySelector('#shadow-guide')?.scrollIntoView({block:'nearest'});return;}
 if(a==='shadow-save')return shadowSaveToJournal();
